// ?clearCellForDiameter@Pathfinder@@QAEHIHHW4PathfindLayerEnum@@H_N@Z
// partial score=0.2414 date=2026-09-28
// Retail 0x003DC810, 729 bytes (ret 0x18). Identity: ILT 0x00048D29 pinned as
// ?clearCellForDiameter@Pathfinder@@QAEHHHHHHH@Z with 14 ILT callers.
// BFME six-arg form of ZH AIPathfind.cpp clearCellForDiameter: UnsignedInt crusher
// vs (signed char) level + trailing Bool stopOnFail + tail recursion; PathfindCell
// type/flags as 3-bit bitfields (retail dword load + cmp dl 0x18); ZH xMinOrMax Bool
// for the corner test; j assigned directly in each corner branch with jMax spilled.
// probe: 745 vs 729 bytes, shape 0.960. Instruction-identical through +0x117; the
// whole residue is ONE block placement: retail lays the not-clear block (stopOnFail
// test + tail recursion) INLINE right after the crushable-level compare, with the
// `jbe` at +0x11B jumping OVER it to the type check at +0x142. VC7.1 always moves
// that block after the inner loop (`ja` far at +0x127, block at +0x178), which turns
// the four short backward jumps from the type check into near jumps (+16 bytes).
//
// SESSION 2 (2026-09-29, model space-bunny-free, ~35 min) added 13 further source
// graphs and 5 flag sets. ALL produce byte-identical 745B / 521 diffs / shape 0.960
// with the SAME two structural differences (probe --shape "replace" list):
//   R +0117 mov ecx,[esp+0x10] / R +011b jbe 0x142 / R +011d..+0x139 fail block
//   O +0127 ja 0x178                                              (1 insn)
//   O +0178..+0x194 the same fail block, out of line          (10 insn)
// New variants tried and DISPROVED for placement (all 745B, identical bytes):
//  - vA  fail label as the sole then-arm, obj-null `goto CheckType`      (537B: the
//       separate CheckType label changed getCell's inline shape, worse)
//  - vB  Retry-label loop with a temp forced to load/sub/store            (compile err)
//  - vC  mega-OR whose then-arm IS the fail block, label at block start  (745B, 0.960)
//  - vD  type check written BEFORE the crush check                        (717B, 0.544)
//  - vF  fail body as the FALL-THROUGH of the crush test, type check behind
//       a `goto CheckType` label (exactly retail's jbe-over-the-block shape) (745B)
//  - vG  vF with the obj-null and flags!=FIXED paths sharing one goto    (745B)
//  - w1  fail as then-arm with an explicit TypeOk fall-through label      (745B)
//  - w2  mega-OR with the INVERTED stopOnFail test (`if (!stopOnFail)`)  (745B)
//  - w3  positive type-check chain (type==OBSTACLE && crusher && fence)    (745B, 0.944)
//  - x1  TWO textual fail copies (A = mega-OR fall-through, B = type-check goto)
//  - x2  THREE-way two copies: null->FailA goto, crush fall-through A, type->FailB
// NEW FINDING (x1/x2): with exactly TWO textual copies of the fail body VC7.1 DOES
// tail-merge them into the single out-of-line block (777B three copies did not, and
// neither do these). So the block POSITION is chosen by the merge, not by source
// order or by any graph edge: the merged node is always sunk after the inner loop.
// Flag sets tried, all 745B/0.960 except the de-optimised ones: /O2 /Ob0 (549B),
// /O1 (452B), /O2 /Ob1, /O2 /Ob2 /GS-, /DNDEBUG /MD /EHsc. The default /O2 /Ob1
// neighbourhood is already the best of the flag space, so no per-file `// cl:`
// override is warranted (neighbours 0x003DC510 and 0x003DCD80 matched at /O2).
// CONCLUSION: 16 source graphs and 5 flag sets now all outline the shared fail
// block identically. The residue is compiler-internal block placement after
// tail-merge, not a source-structure or spelling difference. blocker=codegen-order/
// fail-block-placement-after-tail-merge. Do not spend another session on graph
// shapes; the only remaining lever is a different compiler build.
//
// SESSION 3 (2026-09-30, model space-bunny-free, ~40 min) confirmed the 745B /
// 521-diff / shape-0.960 baseline reproduces byte-for-byte and then CLOSED the
// question with a size-accounting proof instead of another graph.
//
// (1) EXACT +16 ACCOUNTING (this CORRECTS the two earlier headers, which said
//     "the four short backward jumps from the type check become near"). A
//     difflib alignment of the masked streams (tools in build/scratch810/) shows
//     the whole +16 is four widened CONDITIONAL jumps, all inside the bounds/
//     null part of the loop, and that the type-check jumps are already short in
//     both builds and cost nothing:
//       R+009c jg 0x11d (2B short) -> O+009c jg 0x17c (6B near)  +4
//       R+00a1 jl 0x11d (2B short) -> O+00a5 jl 0x17c (6B near)  +4
//       R+00a6 jg 0x11d (2B short) -> O+00ae jg 0x17c (6B near)  +4
//       R+00dd je 0x11d (2B short) -> O+00e9 je 0x17c (6B near)  +4
//     R+0093 jl is ALREADY a 6-byte near jcc in retail (0x11d-0x99 = 0x84 = 132
//     > 127), so it costs nothing either way. The +37/-37 block move of the
//     fail code is size-neutral; the extra `mov ecx,[esp+0x10]` at ours +0x178
//     is offset by retail's own second reload at +0x13e. The single insert/delete
//     pair at +0x2a6/+0x2aa (loop-latch reload order, 4B each way) nets zero.
//
// (2) THE PLACEMENT WINDOW IS A SINGLE POINT. Those four jumps force the fail
//     block's first byte T to satisfy BOTH:
//       R+0093 jl must stay NEAR  => T - 0x99 >  127 => T >= 0x11A
//       R+009c jg must stay SHORT => T - 0x9e <= 127 => T <= 0x11D
//     so T is in [0x11A, 0x11D] and the type-check's four backward jumps are
//     short across that whole range. Retail uses T = 0x11D. There is no nearby
//     alternative that would also match: the fail block must be the FALL-THROUGH
//     of the crush-level compare, sitting between the `jbe` and the type check.
//     That is one discrete block-order decision, not a size gradient.
//
// (3) FLAG SWEEP EXTENDED to 16 sets (session 2 did 5). Only three differ at all
//     and none is better: /Ots 452B (shape 0.407), /Oy- 711B (0.756),
//     /arch:SSE2 750B (0.871). Identical 745B/0.960 for: default, /Oi-, /Ot,
//     /Gr, /GF, /Zp16, /favor:blend, /arch:SSE, /fp:fast, /Zl, /Gs1000000,
//     /opt:ref /opt:icf, /Oi /Ot /Oy- /favor:blend. The flag space is closed.
//
// (4) EIGHT NEW SOURCE GRAPHS, all byte-identical 745B / 521 diffs / shape 0.960
//     (build/scratch810/new/): n1 Fail label LAST in the loop body with a
//     trailing `continue` (mega-OR form); n2 fail body as the explicit else arm
//     (invalid - the type check's goto lost its label; superseded by n4/y1);
//     n3 fail body wrapped in `do{}while(0)`; n4 the crush verdict hoisted into
//     a `Bool tooHard` local (invalid label, same reason); n5 the crush compare
//     inverted to `!(level <= crusher)`; n6 early gotos, Fail last, obj in its
//     own scope; n7 an explicit `Retry:` label at the top of the function with
//     `pathDiameter = pathDiameter - 2; stopOnFail = false; goto Retry` (invalid
//     label); n8 the same goto-Retry form with the fail code in BOTH places ->
//     731B / 524 diffs / shape 0.948, the same far placement, i.e. reproducing
//     session 1's t810e; y1 the ZH-style POSITIVE nesting (`if (cell) {...} else
//     {FAIL}`) with the fail block in the else arm; y2 the positive nesting with
//     the fail code inline in the then-arm and a `Fail:` label after the type
//     check. y1/y2 are the spellings the EA source most likely used, given the
//     Zero Hour twin's `if (cell) {...} else { return false; }`, and both still
//     outline the block.
// (5) tools/shape_family_levers.py over all ten families emits only 2 choices
//     (4 combinations: the two jMax/j operand orders); tools/shape_search.py ran
//     all four, best shape score 0.279 (745B), nothing near 0.960. The finite
//     mechanical space agrees with the hand graphs.
//
// VERDICT for session 3: 26 source graphs, 16 flag sets and the mechanical
// choice generator all place the merged fail block after the inner loop, and the
// +16 is provably the four bounds/null jcc widenings that follow from it. The
// residue is a single MSVC block-placement decision and is not reachable by
// source shaping. Recommend the parent retire this body from the conversion queue
// (or route it to a build/compiler-variant lane) rather than assign another
// graph-shape session. blocker=codegen-order/fail-block-placement-after-tail-merge
// Artifacts: build/scratch810/s3_retail.bin, build/scratch810/s3_ours.bin,
// build/scratch810/s3_base.txt, build/scratch810/align.py,
// build/scratch810/flags/ (16 flag variants), build/scratch810/new/ (n1-n8, y1, y2),
// build/scratch810/choices.json, build/scratch810/sweep.sh,
// build/scratch810/run_new.sh, build/scratch810/gen_new.py.
// Full retail capstone decode: build/scratch810/retail810.txt (base 0x3DC810).
// SESSION 1 (model muse-spark-1.3-free, ~60 min) proved/disproved:
// - Fail at +0x11D has TEN entries: bounds x4 fwd, map-null fwd, crush fall-through,
//   type x4 BACKWARD; obj-null jumps fwd to +0x13e (extra mov ecx) then CheckType.
//   Small-loop fails jump DIRECT to the shared return-0 epilogue at +0x2CD.
// - Retry-loop theory (fail without a call stays inline): DISPROVED for placement.
//   t810e (shared label + pathDiameter=pathDiameter-2/sub[mem]+goto Retry): 731B but
//   fail STILL far; temp-forced load/sub/store refolds to sub[mem] (t810f, also 731B).
// - Disproved for placement (all still outline the shared block far, 745B unless
//   noted): bottom-loop goto label (t810a), goto-over+fallthrough (t810b), nested
//   ifs (t810c), 3 textual copies -> TWO far copies 777B (t810d: no tail merging),
//   mega-OR + single back-goto (t810g = this file, and t810f retry variant 731B).
// Compare build/scratch810/ours810e.txt (t810e bytes) vs retail810.txt directly.
//
typedef int Int;
typedef bool Bool;
typedef unsigned int UnsignedInt;
typedef unsigned char UnsignedByte;
typedef unsigned int ObjectID;

const ObjectID INVALID_ID = 0;

struct ICoord2D { Int x, y; };
struct IRegion2D { ICoord2D lo, hi; };

enum PathfindLayerEnum { LAYER_INVALID = 0, LAYER_GROUND = 1, LAYER_LAST = 15 };

class Object
{
public:
	UnsignedByte getCrushableLevel( void ) const;
};

class GameLogic
{
public:
	Object *findObjectByID( ObjectID id );
};

extern GameLogic *TheGameLogic;

class PathfindCellInfo
{
public:
	unsigned char m_prefix[0x14];
	ObjectID m_goalUnitID;
	ObjectID m_posUnitID;
	ObjectID m_bfme1C;
	ObjectID m_bfme20;
	UnsignedInt m_bfme24;
};

class PathfindCell
{
public:
	enum CellType { CELL_CLEAR = 0, CELL_OBSTACLE = 4 };
	enum CellFlags { NO_UNITS = 0, UNIT_PRESENT_FIXED = 3 };

	Int getType( void ) const { return m_type; }
	Int getFlags( void ) const { return m_flags; }
	ObjectID getPosUnit( void ) const { ObjectID id = m_info ? m_info->m_posUnitID : INVALID_ID; return id; }
	Bool isObstacleFence( void ) const { return m_info && (((unsigned char)(m_info->m_bfme24 >> 1)) & 1); }

	PathfindCellInfo *m_info;
	Int m_unused1;
	Int m_unused2;
	UnsignedInt m_type:3;
	UnsignedInt m_flags:3;
	UnsignedInt m_rest:26;
};

class PathfindLayer
{
public:
	PathfindCell *getCell( Int cellX, Int cellY );

private:
	unsigned char m_body[0x44];
};

class Pathfinder
{
public:
	Int clearCellForDiameter( UnsignedInt crusher, Int cellX, Int cellY, PathfindLayerEnum layer,
		Int pathDiameter, Bool stopOnFail );
	PathfindCell *getCell( PathfindLayerEnum layer, Int cellX, Int cellY );

private:
	unsigned char m_prefix[0x10];
	PathfindCell **m_map;
	IRegion2D m_extent;
	unsigned char m_mid[0x85c - 0x24];
	PathfindLayer m_layers[16];
};

inline PathfindCell *Pathfinder::getCell( PathfindLayerEnum layer, Int cellX, Int cellY )
{
	if (cellX >= m_extent.lo.x && cellX <= m_extent.hi.x &&
		cellY >= m_extent.lo.y && cellY <= m_extent.hi.y)
	{
		if (layer > LAYER_GROUND && layer <= LAYER_LAST)
		{
			PathfindCell *cell = m_layers[layer].getCell( cellX, cellY );
			if (cell)
				return cell;
		}
		return &m_map[cellX][cellY];
	}
	return 0;
}

Int Pathfinder::clearCellForDiameter( UnsignedInt crusher, Int cellX, Int cellY,
	PathfindLayerEnum layer, Int pathDiameter, Bool stopOnFail )
{
	Int radius = pathDiameter/2;
	Int numCellsAbove = radius;
	if (radius==0) numCellsAbove++;
	Int i, j;
	if (radius > 1)
	{
		for (i = cellX - radius; i < cellX + radius; i++)
		{
			Int jMax;
			Bool xMinOrMax = (i == cellX - radius) || (i == cellX + radius - 1);
			if (xMinOrMax)
			{
				jMax = cellY + radius - 1;
				j = cellY - radius + 1;
			}
			else
			{
				jMax = cellY + radius;
				j = cellY - radius;
			}
			for (; j < jMax; j++)
			{
				Object *obj;
				PathfindCell *cell = getCell(layer, i, j);
				if (!cell
					|| (cell->getFlags() == PathfindCell::UNIT_PRESENT_FIXED
						&& ((obj = TheGameLogic->findObjectByID(cell->getPosUnit())) != 0)
						&& (UnsignedInt)(signed char)obj->getCrushableLevel() > crusher))
				{
Fail:
					if (stopOnFail)
						return 0;
					return clearCellForDiameter(crusher, cellX, cellY, layer, pathDiameter - 2, false);
				}
				if (cell->getType() != PathfindCell::CELL_CLEAR)
				{
					if (cell->getType() != PathfindCell::CELL_OBSTACLE || !crusher ||
						!cell->isObstacleFence())
						goto Fail;
				}
			}
		}
	}
	else
	{
		for (i = cellX - radius; i < cellX + numCellsAbove; i++)
		{
			for (j = cellY - radius; j < cellY + numCellsAbove; j++)
			{
				PathfindCell *cell = getCell(layer, i, j);
				if (!cell)
					return 0;
				if (cell->getFlags() == PathfindCell::UNIT_PRESENT_FIXED)
				{
					Object *obj = TheGameLogic->findObjectByID(cell->getPosUnit());
					if (obj && (UnsignedInt)(signed char)obj->getCrushableLevel() > crusher)
						return 0;
				}
				if (cell->getType() != PathfindCell::CELL_CLEAR)
				{
					if (cell->getType() != PathfindCell::CELL_OBSTACLE || !crusher ||
						!cell->isObstacleFence())
						return 0;
				}
			}
		}
	}
	if (radius == 0)
		return 1;
	return 2*radius;
}
